.tactile-btn {
  transition: transform 150ms cubic-bezier(0.16, 1, 0.3, 1), background-color 150ms ease;
  will-change: transform;
}
.tactile-btn:active {
  transform: scale(0.97);
}
@media (prefers-reduced-motion: reduce) {
  .tactile-btn {
    transition: none;
  }
  .tactile-btn:active {
    transform: none;
  }
}

@keyframes modal-in {
  from { opacity: 0; transform: scale(0.95) translateY(4px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}
@keyframes modal-out {
  from { opacity: 1; transform: scale(1) translateY(0); }
  to { opacity: 0; transform: scale(0.97) translateY(2px); }
}
.modal-surface[data-state='open'] {
  animation: modal-in 180ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
.modal-surface[data-state='closed'] {
  animation: modal-out 130ms cubic-bezier(0.4, 0, 1, 1) forwards;
}

.popover-content {
  transform-origin: var(--radix-popover-content-transform-origin, top center);
  transition: transform 140ms cubic-bezier(0.16, 1, 0.3, 1), opacity 140ms ease;
}
.popover-content[data-state='closed'] {
  opacity: 0;
  transform: scale(0.96);
}
.popover-content[data-state='open'] {
  opacity: 1;
  transform: scale(1);
}

.sheet-panel {
  transition: transform 280ms cubic-bezier(0.32, 0.72, 0, 1);
  will-change: transform;
}
.sheet-panel[data-side='right'][data-state='closed'] {
  transform: translate3d(100%, 0, 0);
}
.sheet-panel[data-side='bottom'][data-state='closed'] {
  transform: translate3d(0, 100%, 0);
}
.sheet-panel[data-state='open'] {
  transform: translate3d(0, 0, 0);
}

.toast-item {
  transition: transform 220ms cubic-bezier(0.22, 1, 0.36, 1), opacity 200ms ease;
  transform: translate3d(0, calc(var(--toast-index, 0) * -12px), 0) scale(calc(1 - var(--toast-index, 0) * 0.04));
}

@keyframes subtle-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}
.skeleton-box {
  animation: subtle-pulse 1.8s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
@media (prefers-reduced-motion: reduce) {
  .skeleton-box {
    animation: none;
    opacity: 0.7;
  }
}

.active-pill-indicator {
  transition: transform 160ms cubic-bezier(0.22, 1, 0.36, 1), opacity 160ms ease;
  will-change: transform;
}
